Action: run_sql({'query': "WITH base AS (\n  SELECT \n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    regexp_extract(address, '(?:^|,)\\s*(\\d+[A-Za-z0-9\\s.-]+?)(?:,|$)', 1) as addr_part\n  FROM establishments\n  WHERE address IS NOT NULL\n),\ncleaned AS (\n  SELECT \n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    addr_part,\n    -- Strip suite/unit numbers if present\n    regexp_replace(addr_part, '\\s+#.*|\\s+Ste.*|\\s+Suite.*|\\s+Unit.*', '', 'i') as raw_street\n  FROM base\n  WHERE addr_part != ''\n),\nstreets AS (\n  SELECT\n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    raw_street,\n    -- Strip leading building number\n    regexp_replace(raw_street, '^\\d+\\s+', '') as street_with_dir,\n    -- Also strip leading N/S/E/W direction if present\n    regexp_replace(regexp_replace(raw_street, '^\\d+\\s+', ''), '^(N|S|E|W|NORTH|SOUTH|EAST|WEST)\\s+', '', 'i') as street_base\n  FROM cleaned\n)\nSELECT * FROM streets LIMIT 20;"})

