Action: run_sql({'query': "WITH base AS (\n  SELECT \n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    regexp_extract(address, '(?:^|,)\\s*(\\d+[A-Za-z0-9\\s.-]+?)(?:,|$)', 1) as addr_part\n  FROM establishments\n  WHERE address IS NOT NULL\n),\ncleaned AS (\n  SELECT \n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    regexp_replace(addr_part, '\\s+#.*|\\s+Ste.*|\\s+Suite.*|\\s+Unit.*|\\s+Bldg.*|\\s+Building.*', '', 'i') as raw_street\n  FROM base\n  WHERE addr_part != ''\n),\nstreets AS (\n  SELECT\n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    -- Strip leading building number\n    trim(regexp_replace(raw_street, '^\\d+\\s+', '')) as street_with_dir,\n    -- Strip directional prefixes like N, S, E, W, North, South, East, West\n    trim(regexp_replace(regexp_replace(raw_street, '^\\d+\\s+', ''), '^(N|S|E|W|NORTH|SOUTH|EAST|WEST)\\s+', '', 'i')) as street_base\n  FROM cleaned\n)\nSELECT \n  street_base,\n  COUNT(CASE WHEN avg_rating >= 3.0 AND avg_rating < 4.0 THEN 1 END) as count_3_to_4_star,\n  COUNT(CASE WHEN round(avg_rating) = 3 THEN 1 END) as count_round_3_star,\n  COUNT(CASE WHEN avg_rating = 3.0 THEN 1 END) as count_exact_3_star\nFROM streets\nWHERE street_base != ''\nGROUP BY street_base\nORDER BY count_3_to_4_star DESC\nLIMIT 20;"})

